(()=>{
'use strict';const F=window.Fleet,h=F.h;
let mapLayer='vehicles',mapPopup=true,attentionOnly=false;
const destination=p=>p?.destination||'张江运营中心';
const car=id=>F.state.vehicles.find(v=>v.id===id);
function stats(){return [{name:'全部车队',n:F.state.vehicles.length,color:'#c9d3e8',detail:'演示车队 · 唯一车辆编号',filter:'all'},{name:'执行任务',n:F.state.vehicles.filter(v=>v.status==='running').length,color:'#79d5ff',detail:'任务运行中',filter:'running'},{name:'待命可用',n:F.state.vehicles.filter(v=>['standby','waiting'].includes(v.status)).length,color:'#11c99b',detail:'可分配运行计划',filter:'standby'},{name:'补能充电',n:F.state.vehicles.filter(v=>v.status==='charging').length,color:'#ffb300',detail:'超充 · 排队补能',filter:'charging'},{name:'维保检查',n:F.state.vehicles.filter(v=>['maintenance','offline'].includes(v.status)).length,color:'#a5b7d0',detail:'包含离线与维保车辆',filter:'maintenance'},{name:'待处理警报',n:F.state.vehicles.filter(v=>v.status==='offline').length+F.state.plans.filter(p=>p.status==='waiting'&&p.vehicleId==='RT-021').length,color:'#ff4b5e',detail:'发车待确认 · 通信告警',filter:'alerts'}];}
function map(){const v=F.vehicle(),p=F.state.plans.find(p=>p.vehicleId===v.id&&p.status!=='cancelled');return `<div class="fleet-map"><img src="assets/map-base.jpg" alt="原稿地图素材，非实时地理位置"><div class="map-grid"></div><svg class="map-route" viewBox="0 0 800 530" preserveAspectRatio="none"><path d="M235 360 C260 225 365 285 425 212 S530 170 635 165" fill="none" stroke="#e6bc31" stroke-width="3" stroke-dasharray="5 5" opacity=".8"/><path d="M165 89 625 40 774 168 763 473 453 510 115 409Z" fill="#2d8bc61a" stroke="#4088b244" stroke-dasharray="8 5"/></svg>${mapLayer==='heat'?'<div class="map-heat"></div>':''}${mapLayer==='fence'?'<div class="map-fence"></div>':''}${[['RT-021',31,56,'#ffb300'],['RT-034',23,30,'#10bc8f'],['RT-041',63,22,'#9763ff'],['RT-008',77,72,'#4e94ff']].map(([id,x,y,c])=>`<button class="map-pin ${F.state.selectedId===id?'selected':''}" style="left:${x}%;top:${y}%;--color:${c}" data-action="overview-pin" data-id="${id}" aria-label="地图车辆 ${id}"><span>${id} · ${F.status[car(id).status][0]} ${car(id).soc}%</span><i>${F.icon('vehicles',13)}</i></button>`).join('')}<div style="position:absolute;left:49%;top:31%;color:#a6d9f5;background:#10212dd9;padding:8px 12px;font-size:11px">${F.icon('flow',16)} 张江运营中心<br><small>补能与维保基地 · 6 桩空闲</small></div>${mapPopup?`<div class="map-info"><h3>${h(v.id)} ${F.badge(v.status)}<button class="close" data-action="overview-close-popup" aria-label="关闭车辆地图信息">×</button></h3><div class="mini-metrics"><div>电池电量<strong class="amber">${v.soc}%</strong></div><div>车内状态<strong class="green">${v.status==='running'?'载客':'空舱'}</strong></div><div>模拟时延<strong class="blue">${v.status==='offline'?'--':'22 ms'}</strong></div></div><p>${h(p?.origin||v.location)} → ${h(destination(p))}</p><div class="row"><button class="btn small soft" data-action="vehicle" data-id="${h(v.id)}">${F.icon('check',14)} 检查发车条件</button><button class="btn small" data-action="overview-remote" data-id="${h(v.id)}">${F.icon('remote',14)} 远程控制</button></div></div>`:''}<span class="map-layer-label">${mapLayer==='heat'?'热力密度 · 模拟需求分布':mapLayer==='fence'?'网格围栏 · 张江运营区域':'原稿地图 · 演示车辆位置'}</span></div>`;}
function alerts(){const v=car('RT-021'),isRunning=v.status==='running';return `<section class="panel alert-panel"><div class="panel-title"><h3>待处理</h3><small class="muted">按优先级排序</small></div><article class="alert-card" style="--accent:${isRunning?'#10bd8e':'#ffb300'}"><div class="row"><strong>RT-021</strong>${F.badge(v.status)}<time>10:19</time></div><p>${isRunning?'车辆已模拟发车，正在前往补能站。':'回场补能计划已生成，等待核验指令放行。'}</p><div class="row"><button class="btn small soft" data-action="vehicle" data-id="RT-021">${isRunning?'查看运行状态':'发车确认'}</button><button class="btn small" data-action="overview-remote" data-id="RT-021">进入工作台</button></div></article><article class="alert-card" style="--accent:#75cfff"><div class="row"><strong>RT-008</strong><span class="badge amber">延误 +7m</span><time>10:15</time></div><p>金科路拥堵，已生成建议绕行路径（+1.2 km）。</p><div class="row"><button class="btn small blue" data-action="overview-reroute">改道建议</button><button class="btn small" data-action="overview-remote" data-id="RT-008">代沟通</button></div></article><article class="alert-card" style="--accent:#ff4b5e"><div class="row"><strong>RT-046</strong>${F.badge(car('RT-046').status)}<time>09:42</time></div><p>${car('RT-046').workOrder?'已创建维保工单，等待现场处理。':'基站 5G 信号中断，位于维保厂区西侧。'}</p><button class="btn small wide" data-action="overview-maintenance">${car('RT-046').workOrder?'查看工单':'排查并派工'}</button></article></section>`;}
function taskTable(plans,overview=false){return `<div class="table-wrap"><table><thead><tr><th>计划编号</th><th>车辆编号</th><th>计划类型</th><th>状态</th><th>起始 / 目的地</th><th>计划时间</th><th>快捷操作</th></tr></thead><tbody>${plans.map(p=>`<tr><td><button class="btn link small" data-action="select-plan" data-id="${h(p.id)}">${h(p.id)}</button></td><td><button class="btn link small" data-action="vehicle" data-id="${h(p.vehicleId)}"><strong>${h(p.vehicleId)}</strong></button></td><td>${h(p.type)}</td><td>${F.badge(p.status)}</td><td title="${h(p.origin+' → '+p.destination)}">${h(p.origin)} → ${h(p.destination)}</td><td class="mono">${h(p.start)} – ${h(p.end)}</td><td><button class="btn small ${p.status==='waiting'?'soft':''}" data-action="${overview?'overview-task':'schedule-select'}" data-id="${h(p.id)}">${p.status==='waiting'?'审核计划':'查看详情'}</button></td></tr>`).join('')}</tbody></table>${plans.length?'':'<div class="empty-state"><h3>没有符合条件的计划</h3><p>调整筛选条件，或创建一个新计划。</p></div>'}</div>`;}
F.pages.overview={render(){return `<section class="overview-page"><div class="page-head overview-head"><h1><i class="status-dot"></i> 车队总览</h1><div class="segmented"><button class="${!attentionOnly?'active':''}" data-action="overview-all">全部</button><button class="${attentionOnly?'active':''}" data-action="overview-attention">仅看关注事项 <span class="badge amber">3</span></button></div></div><div class="stat-grid">${stats().map(s=>`<button class="stat-card" style="--accent:${s.color}" data-action="overview-stat" data-filter="${s.filter}"><span class="stat-label">${s.name}${F.icon(s.filter==='charging'?'battery':'vehicles',15)}</span><strong>${s.n}</strong><small>${s.filter==='alerts'?'项':'辆'}</small><p>${s.detail}</p></button>`).join('')}</div><div class="overview-body"><section class="panel map-panel"><div class="panel-title"><h3>车队态势监控图</h3><div class="map-tools">${[['vehicles','车辆图层'],['heat','热力密度'],['fence','网格围栏']].map(([k,t])=>`<button class="${mapLayer===k?'active':''}" data-action="overview-layer" data-layer="${k}">${t}</button>`).join('')}<button data-action="overview-map-expand" aria-label="放大地图">⛶</button></div></div>${map()}</section>${alerts()}</div><section class="panel overview-tasks"><div class="panel-title"><h3>${attentionOnly?'关注任务':'运行任务'} <small class="muted"> / ${F.state.plans.filter(p=>p.status!=='cancelled').length} 项演示计划</small></h3><button class="btn link small" data-action="go" data-route="plans">全部 ${F.icon('arrow',14)}</button></div>${taskTable(F.state.plans.filter(p=>!attentionOnly||p.status==='waiting'),true)}</section></section>`;},action(a,b){if(commonActions(a,b))return;if(a==='overview-pin'){F.state.selectedId=b.dataset.id;mapPopup=true;F.render();}if(a==='overview-close-popup'){mapPopup=false;F.render();}if(a==='overview-layer'){mapLayer=b.dataset.layer;F.render();}if(a==='overview-attention'||a==='overview-all'){attentionOnly=a==='overview-attention';F.render();}if(a==='overview-stat'){if(b.dataset.filter==='alerts'){attentionOnly=true;F.render();document.querySelector('.alert-panel').scrollIntoView({block:'center',behavior:'smooth'});}else{F.state.vehicleFilter=b.dataset.filter;F.go('vehicles');}}if(a==='overview-remote'){F.state.selectedId=b.dataset.id;F.save();F.go('remote');}if(a==='overview-task'){selectPlan(b.dataset.id);F.go('detail');}if(a==='overview-map-expand'){F.modal('车队态势监控图 · 原稿素材',`<img class="screenshot-preview" src="assets/map-base.jpg" alt="原稿地图"><p class="detail-video-title">演示地图，不代表实时地理位置或导航结果。</p><div class="dialog-actions"><button class="btn primary">关闭</button></div>`);}if(a==='overview-reroute')reroute();if(a==='overview-maintenance')maintenance();}};
function reroute(){F.modal('RT-008 · 改道建议',`<p class="dialog-description">原路线受金科路施工影响，预计延误 7 分钟。建议经祖冲之路绕行，增加 1.2 km，演示预计减少 4 分钟延误。</p><div class="divider"></div><label class="field"><span>绕行策略</span><select name="strategy"><option>采用建议路线 · 预计 10:58 到达</option><option>保持原路线 · 预计 11:02 到达</option></select></label><p class="muted">只更新演示计划，不连接导航或车控服务。</p><div class="dialog-actions"><button type="button" class="btn subtle" data-action="close-modal">取消</button><button class="btn primary">应用方案</button></div>`,data=>{const p=F.state.plans.find(p=>p.vehicleId==='RT-008');if(p){p.note=data.get('strategy');p.end=data.get('strategy').startsWith('采用')?'10:58':'11:02';}F.log('RT-008 模拟调整路线：'+data.get('strategy'));F.toast('路线方案已记录到演示计划');F.render();});}
function maintenance(){const v=car('RT-046');if(v.workOrder){F.modal('维保工单 '+v.workOrder.id,`<p class="dialog-description">车辆：RT-046<br>处理人：${h(v.workOrder.owner)}<br>问题：${h(v.workOrder.issue)}<br>状态：待现场处理</p><div class="dialog-actions"><button class="btn primary">关闭</button></div>`);return;}F.modal('RT-046 · 创建维保工单',`<label class="field"><span>故障描述</span><textarea name="issue" required>5G 通信中断，请检查车载通信模块与电源。</textarea></label><label class="field"><span>指派班组</span><select name="owner"><option>维保组 #03 · 王工</option><option>通信保障组 #02 · 李工</option></select></label><p class="muted">本地模拟工单，不会通知现场人员。</p><div class="dialog-actions"><button type="button" class="btn subtle" data-action="close-modal">取消</button><button class="btn primary">创建演示工单</button></div>`,data=>{v.workOrder={id:'WO-'+String(F.state.logs.length+1001),issue:data.get('issue'),owner:data.get('owner')};F.log('RT-046 已创建演示维保工单 '+v.workOrder.id);F.toast('维保工单已保存');F.render();});}
let scheduleView='timeline',scheduleQuery='',scheduleType='all',scheduleStatus='all',scheduleDate='2026-10-23',scheduleRange='today';
let scheduleRoot=null,scheduleAxis=null,cursorDrag=null,cursorMinute=620;
const minutes=t=>{const [hh,mm]=t.split(':').map(Number);return hh*60+mm;};
const dayMinute=date=>Date.parse(date+'T00:00:00Z')/60000;
const clockText=value=>{const m=((Math.round(value)%1440)+1440)%1440;return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');};
const planStart=p=>dayMinute(p.date||'2026-10-23')+minutes(p.start);
const planEnd=p=>dayMinute(p.date||'2026-10-23')+minutes(p.end);
F.status.scheduled=['未触发','muted'];
function ensureScheduleExamples(){
  if(F.state.scheduleExamplesVersion===1)return;
  const samples=[
    ['H-1023-021','RT-021','接送任务','08:30','10:00','completed','早班接送','金科路地铁站','浦东软件园'],
    ['P-1023-101','RT-021','回场补能','11:00','12:30','scheduled','超快充补能占用','4 号超充桩','4 号超充桩'],
    ['P-1023-102','RT-021','循环运行','13:10','14:25','scheduled','园区巡游','张江运营中心','张江北区'],
    ['P-1023-103','RT-021','接送任务','15:00','16:30','scheduled','晚班接驳','浦东软件园','金科路地铁站'],
    ['P-1023-104','RT-008','循环运行','11:40','13:00','scheduled','巡游待命','浦东软件园','张江环线'],
    ['P-1023-105','RT-008','接送任务','14:00','15:20','scheduled','预约接送','张江环线','广兰路地铁站'],
    ['P-1023-106','RT-034','接送任务','11:30','13:00','scheduled','高峰接送','嘉定热点区','园区主入口'],
    ['P-1023-107','RT-034','车辆调位','14:30','16:00','scheduled','下午调位','园区主入口','张江北区'],
    ['P-1023-108','RT-041','循环运行','11:00','12:20','scheduled','充后巡游','张江运营基地','园区环线'],
    ['P-1023-109','RT-041','接送任务','13:30','15:00','scheduled','午后接送','园区环线','浦东软件园'],
    ['P-1023-110','RT-046','车辆调位','16:20','17:30','scheduled','维保后验证','维修厂区','封闭测试道路']
  ];
  for(const [id,vehicleId,type,start,end,status,title,origin,destination] of samples){
    if(F.state.plans.some(p=>p.id===id)||!F.state.vehicles.some(v=>v.id===vehicleId))continue;
    if(F.state.plans.some(p=>p.vehicleId===vehicleId&&(p.date||'2026-10-23')==='2026-10-23'&&p.status!=='cancelled'&&minutes(start)<minutes(p.end)&&minutes(end)>minutes(p.start)))continue;
    F.state.plans.push({id,vehicleId,type,start,end,status,title,origin,destination,date:'2026-10-23',scheduleExample:true});
  }
  const delayed=F.state.plans.find(p=>p.id==='T-1023-094');if(delayed&&delayed.delayMinutes==null)delayed.delayMinutes=7;
  F.state.scheduleExamplesVersion=1;F.save();
}
ensureScheduleExamples();
function rangeBounds(){const base=dayMinute(scheduleDate);return {start:base+(scheduleRange==='today'?0:480),end:base+(scheduleRange==='today'?1440:scheduleRange==='24h'?1920:3960)};}
function filteredPlans(){const range=rangeBounds();return F.state.plans.filter(p=>planStart(p)<range.end&&planEnd(p)>range.start&&(scheduleType==='all'||p.type===scheduleType)&&(scheduleStatus==='all'||p.status===scheduleStatus)&&(!scheduleQuery||[p.id,p.vehicleId,p.origin,p.destination,p.title].join(' ').toLowerCase().includes(scheduleQuery.toLowerCase())));}
function axisFor(list){
  const base=dayMinute(scheduleDate),range=rangeBounds();
  const start=scheduleRange==='today'?Math.min(base+480,...list.map(p=>Math.floor(planStart(p)/60)*60)):range.start;
  const end=scheduleRange==='today'?Math.max(base+1080,...list.map(p=>Math.ceil(planEnd(p)/60)*60)):range.end;
  return {start,end,span:end-start,step:scheduleRange==='today'?60:scheduleRange==='24h'?120:360,width:Math.max(900,(end-start)*(scheduleRange==='today'?1.5:scheduleRange==='24h'?.85:.6))};
}
function cursorAbsolute(){return dayMinute(scheduleDate)+cursorMinute;}
function phaseFor(p){
  const time=cursorAbsolute();
  if(p.status==='cancelled')return 'cancelled';
  if(time<planStart(p))return 'scheduled';
  if(time>=planEnd(p)||p.status==='completed')return 'completed';
  if(p.type==='停运检修')return 'maintenance';
  if(p.status==='running'&&p.delayMinutes)return 'delayed';
  if(p.status==='waiting'&&p.id==='D-1023-012')return 'standby';
  return p.status==='scheduled'?'running':p.status;
}
const phaseLabels={scheduled:'未触发',completed:'已完成',maintenance:'停运维护',delayed:'延误',standby:'待命中',running:'执行中',waiting:'待发车',cancelled:'已取消'};
function cardTheme(p,phase){return ['scheduled','completed','maintenance','delayed','standby','cancelled'].includes(phase)?phase:p.type==='回场补能'&&phase==='running'?'charging':phase;}
function planTitle(p){return p.title||(p.id==='D-1023-012'?'待命调度':p.type==='停运检修'?'激光雷达与 RTK 定位系统排查':p.type==='回场补能'&&p.status==='running'?'直流超充':p.type);}
function planBadge(p){const phase=phaseFor(p);return `<span class="dispatch-status ${phase}">${phaseLabels[phase]||h(phase)}</span>`;}
function taskNote(p,phase){
  if(p.status==='scheduled')return phase==='scheduled'?'预排班 · 尚未触发':'按此时点预览 · '+phaseLabels[phase];
  if(phase==='scheduled')return '预排班 · 尚未触发';
  if(phase==='completed')return p.status==='completed'?'任务已归档':'按此时点预览 · 已完成';
  if(phase==='cancelled')return '计划已取消';
  if(p.type==='停运检修')return '工单负责人：维保组 #03（王工）';
  if(phase==='delayed')return `拥堵 · 延后 ${p.delayMinutes} min`;
  if(p.id==='S-1023-026')return '2号充电站 · 桩02';
  if(p.type==='回场补能')return p.id==='S-1023-028'?'路线已下发 · 预定桩位 #04':'补能泊位已预留';
  return '按计划执行';
}
function taskCard(p,lane=0){
  const phase=phaseFor(p),left=(Math.max(planStart(p),scheduleAxis.start)-scheduleAxis.start)/scheduleAxis.span*100;
  const width=(Math.min(planEnd(p),scheduleAxis.end)-Math.max(planStart(p),scheduleAxis.start))/scheduleAxis.span*100;
  const note=taskNote(p,phase);
  return `<button class="dispatch-task ${cardTheme(p,phase)} ${p.id===F.state.selectedPlan?'is-selected':''}" data-action="schedule-select" data-id="${h(p.id)}" data-phase="${phase}" style="left:${left}%;width:${Math.max(.2,width)}%;top:${18+lane*94}px" aria-label="${h(p.vehicleId+' '+planTitle(p)+' '+p.start+' 至 '+p.end)}" title="${h(p.id+' · '+planTitle(p)+' · '+p.start+'–'+p.end)}"><span class="dispatch-task-top"><span class="task-phase">${phaseLabels[phase]}</span><time>${h(p.start)}–${h(p.end)}</time></span><strong>${p.type==='回场补能'?'ϟ':p.type==='停运检修'?'⚙':'◉'} ${h(planTitle(p))}</strong><small class="task-note">${h(note)}</small></button>`;
}
function vehicleCell(v,selected,plans){
  const offline=['offline','maintenance'].includes(v.status),stateLabel=selected?'当前选中':offline?'离线维护':v.id==='RT-008'&&v.status==='running'?'载客中':F.status[v.status]?.[0]||v.status;
  const delayed=plans.find(p=>p.delayMinutes&&p.status==='running');
  const hint=offline?'传感器离线':v.status==='charging'?(v.id==='RT-041'?'2号充电站 · 桩02':'补能充电中'):v.soc<35?'需补能':delayed?`延后 ${delayed.delayMinutes} min`:v.location||'张江园区';
  return `<button type="button" class="dispatch-vehicle" data-action="schedule-vehicle" data-id="${h(v.id)}" aria-label="选择车辆 ${h(v.id)}" aria-pressed="${selected}" title="选择车辆及当前时点计划"><span class="dispatch-vehicle-top"><strong>${h(v.id)}</strong><span class="vehicle-state ${selected?'selected':offline?'offline':v.status}">${h(stateLabel)}</span>${v.id==='RT-008'?'<span class="passengers">♟ 2</span>':''}<b class="soc ${offline?'offline':v.status==='charging'?'charging':v.soc<35?'low':''}">${offline?'--':v.soc+'%'}</b></span><span class="dispatch-vehicle-meta"><span>${h(v.plate)}${offline?' · 维保厂区':''}</span><span class="vehicle-hint ${offline||delayed?'red':v.soc<35&&v.status!=='charging'?'amber':''}">${h(hint)}</span></span><span class="vehicle-battery ${offline?'offline':v.status==='charging'?'charging':v.soc<35?'low':''}"><i style="width:${offline?100:v.soc}%"></i></span></button>`;
}
function inspector(){
  const p=filteredPlans().find(p=>p.id===F.state.selectedPlan);if(!p)return '<aside class="plan-inspector"><div class="empty-state">选择计划查看详情</div></aside>';
  const v=car(p.vehicleId),phase=phaseFor(p),duration=Math.max(0,minutes(p.end)-minutes(p.start)),progress=Math.round(100*Math.max(0,Math.min(1,(cursorAbsolute()-planStart(p))/Math.max(1,planEnd(p)-planStart(p)))));
  const scheduled=p.status==='scheduled',cancelled=p.status==='cancelled';
  return `<aside class="plan-inspector"><header class="dispatch-inspector-head"><h3>${F.icon('check',20)} 运行计划详情</h3><span class="plan-code">PLAN #${h(p.id)}</span>${planBadge(p)}</header><div class="dispatch-inspector-body"><section class="dispatch-plan-meta"><div><small>车辆</small><button class="plan-vehicle-link" data-action="vehicle" data-id="${h(v.id)}">${h(v.id)}</button><span>${h(planTitle(p))}</span></div><div><small>排班</small><strong>${h(p.start)} - ${h(p.end)}</strong><span class="amber">预计 ${duration} min</span></div></section><section><div class="row between"><strong>进度</strong><span class="inspector-phase ${phase}">${phaseLabels[phase]}</span></div><div class="dispatch-plan-progress"><i style="width:${cancelled?0:progress}%"></i></div><div class="row between dispatch-progress-times"><span>${h(p.start)}</span><span>${h(p.end)}</span></div></section><section class="dispatch-chain"><h3>子任务链</h3><div class="dispatch-chain-step"><div><strong>1. ${h(p.origin)}</strong><span class="green">${phase==='scheduled'?'未触发':phase==='completed'?'已完成':'已校验'}</span></div><p><span>${p.type==='回场补能'?'主入口通道进场':'起点检查与离站'}</span><span>约 ${Math.max(1,Math.round(duration*.33))} min</span></p></div><div class="dispatch-chain-step muted-step"><div><strong>2. ${h(p.destination)}</strong><span>${phase==='completed'?'已完成':'待执行'}</span></div><p><span>${p.type==='回场补能'?'泊位对位与补能准备':'到达目标站点并完成任务'}</span><span>约 ${Math.max(1,Math.round(duration*.12))} min</span></p></div>${p.note?`<p class="dispatch-note">${h(p.note)}</p>`:''}</section><div class="resource-ok ${scheduled?'scheduled':''}">${scheduled?'◷ 预排班已登记 · 等待计划触发':cancelled?'该计划已取消':'◇ 时空资源预检通过'+(p.id==='S-1023-028'?' · 桩位 #04 已就绪':p.id==='S-1023-026'?' · 桩位 #02 充电中':' · 可继续核验车辆')}</div><button class="btn primary wide dispatch-remote" data-action="schedule-remote" ${cancelled||scheduled?'disabled':''}>${F.icon('remote',18)} ${scheduled?'排班尚未触发':'进入远程运营实时接管'}</button><div class="dispatch-secondary"><button class="btn subtle" data-action="schedule-time" ${['cancelled','completed'].includes(p.status)?'disabled':''}>${F.icon('clock',16)} 调整时段</button><button class="btn subtle" data-action="schedule-switch" ${!['waiting','scheduled'].includes(p.status)?'disabled':''}>↔ 换车执行</button></div><button class="btn wide link dispatch-cancel" data-action="schedule-cancel" ${['cancelled','completed'].includes(p.status)?'disabled':''}>⊗ 取消计划</button></div></aside>`;
}
function timelineMarkup(list){
  const groups=new Map();list.forEach(p=>{if(!groups.has(p.vehicleId))groups.set(p.vehicleId,[]);groups.get(p.vehicleId).push(p);});
  const order=['RT-021','RT-008','RT-034','RT-041','RT-046'];
  const vehicles=[...groups.keys()].sort((a,b)=>{const ai=order.indexOf(a),bi=order.indexOf(b);return (ai<0?99:ai)-(bi<0?99:bi)||a.localeCompare(b);});
  const ticks=[];for(let t=scheduleAxis.start;t<=scheduleAxis.end;t+=scheduleAxis.step)ticks.push(t);if(ticks[ticks.length-1]!==scheduleAxis.end)ticks.push(scheduleAxis.end);
  const rows=vehicles.map(id=>{
    const plans=groups.get(id).sort((a,b)=>planStart(a)-planStart(b)),lanes=[],placements=[];
    plans.forEach(p=>{let lane=lanes.findIndex(end=>end<=planStart(p));if(lane<0)lane=lanes.length;lanes[lane]=planEnd(p);placements.push([p,lane]);});
    const active=plans.some(p=>p.id===F.state.selectedPlan);
    return `<div class="dispatch-row ${active?'is-selected':''}" style="height:${Math.max(124,lanes.length*94+30)}px">${vehicleCell(car(id),active,plans)}<div class="dispatch-track">${placements.map(([p,lane])=>taskCard(p,lane)).join('')}</div></div>`;
  }).join('');
  return `<div class="dispatch-scroll"><div class="dispatch-grid" style="--track-width:${scheduleAxis.width}px;--grid-step:${scheduleAxis.step/scheduleAxis.span*100}%"><div class="dispatch-heading"><div class="dispatch-vehicle-heading">${F.icon('vehicles',17)} 受控编排车辆 <small>SOC / 状态</small></div><div class="dispatch-hours">${ticks.map((t,index)=>`<span class="${index===0?'first':index===ticks.length-1?'last':''}" style="left:${(t-scheduleAxis.start)/scheduleAxis.span*100}%">${scheduleRange==='today'?clockText(t):new Date(t*60000).toISOString().slice(5,10)+' '+clockText(t)}</span>`).join('')}</div></div>${rows||'<div class="schedule-empty">没有符合条件的排班，可切换日期或清除筛选。</div>'}<div class="dispatch-grid-spacer"></div><div class="dispatch-cursor" role="slider" tabindex="0" aria-label="拖动时间游标" aria-orientation="horizontal"><span class="cursor-label"><i></i><b></b></span><span class="cursor-line"></span></div></div></div>`;
}
function summaryMarkup(list){const counts={};list.forEach(p=>{const phase=phaseFor(p);counts[phase]=(counts[phase]||0)+1;});return `<span>当前编排任务：<b>${list.length}</b> 项</span><span><i class="legend-dot running"></i>正在执行：<b>${(counts.running||0)+(counts.delayed||0)+(counts.maintenance||0)}</b></span><span><i class="legend-dot scheduled"></i>未触发：<b>${counts.scheduled||0}</b></span><span><i class="legend-dot delayed"></i>异常延误：<b>${counts.delayed||0}</b></span><span class="cursor-explainer">拖动红线预览排班时点</span>`;}
function scheduleContents(){const list=filteredPlans();if(list.length&&!list.some(p=>p.id===F.state.selectedPlan)){F.state.selectedPlan=list[0].id;F.state.selectedId=list[0].vehicleId;}scheduleAxis=axisFor(list);cursorMinute=Math.max(scheduleAxis.start-dayMinute(scheduleDate),Math.min(scheduleAxis.end-dayMinute(scheduleDate),cursorMinute));return `<div class="schedule-layout"><div class="schedule-main">${scheduleView==='list'?`<div class="schedule-list">${taskTable(list)}</div>`:timelineMarkup(list)}</div>${inspector()}</div><footer class="schedule-foot">${summaryMarkup(list)}</footer>`;}
function updateCursor(){
  if(!scheduleRoot||!scheduleAxis)return;const cursor=scheduleRoot.querySelector('.dispatch-cursor');
  if(cursor){
    const ratio=(cursorAbsolute()-scheduleAxis.start)/scheduleAxis.span;
    const width=scheduleRoot.querySelector('.dispatch-hours')?.clientWidth||scheduleAxis.width;
    cursor.style.left=`calc(var(--vehicle-width) + ${ratio*width}px)`;
    cursor.setAttribute('aria-valuemin',String(scheduleAxis.start-dayMinute(scheduleDate)));cursor.setAttribute('aria-valuemax',String(scheduleAxis.end-dayMinute(scheduleDate)));cursor.setAttribute('aria-valuenow',String(cursorMinute));
    const date=new Date(cursorAbsolute()*60000).toISOString().slice(0,10),text=(cursorMinute===620?'当前 ':'预览 ')+(date!==scheduleDate?date.slice(5)+' ':'')+clockText(cursorMinute);
    cursor.setAttribute('aria-valuetext',date+' '+clockText(cursorMinute));cursor.querySelector('b').textContent=text;cursor.querySelector('.cursor-label').classList.toggle('at-end',ratio>.88);
  }
}
function updateTimePreview(){
  updateCursor();scheduleRoot.querySelectorAll('.dispatch-task').forEach(el=>{const p=F.state.plans.find(p=>p.id===el.dataset.id);if(!p)return;const phase=phaseFor(p);el.className=`dispatch-task ${cardTheme(p,phase)} ${p.id===F.state.selectedPlan?'is-selected':''}`;el.dataset.phase=phase;el.querySelector('.task-phase').textContent=phaseLabels[phase];const note=el.querySelector('.task-note');note.textContent=taskNote(p,phase);});
  const panel=scheduleRoot.querySelector('.plan-inspector');if(panel)panel.outerHTML=inspector();const footer=scheduleRoot.querySelector('.schedule-foot');if(footer)footer.innerHTML=summaryMarkup(filteredPlans());
}
function saveCursor(){F.state.scheduleCursor={date:scheduleDate,range:scheduleRange,minute:cursorMinute};F.save();}
function mountSchedule(root){
  scheduleRoot=root;const controller=new AbortController(),signal=controller.signal;
  updateCursor();
  root.querySelector('#schedule-search').addEventListener('input',e=>{scheduleQuery=e.target.value;root.querySelector('#schedule-content').innerHTML=scheduleContents();updateCursor();},{signal});
  root.querySelector('#schedule-type').addEventListener('change',e=>{scheduleType=e.target.value;F.render();},{signal});
  root.querySelector('#schedule-status').addEventListener('change',e=>{scheduleStatus=e.target.value;F.render();},{signal});
  root.querySelector('#schedule-date').addEventListener('change',e=>{if(e.target.value){scheduleDate=e.target.value;cursorMinute=620;saveCursor();F.render();}},{signal});
  const moveCursor=e=>{const hours=root.querySelector('.dispatch-hours');if(!hours)return;const rect=hours.getBoundingClientRect(),ratio=Math.max(0,Math.min(1,(e.clientX-cursorDrag.offset-rect.left)/rect.width));cursorMinute=Math.round((scheduleAxis.start-dayMinute(scheduleDate)+ratio*scheduleAxis.span)/5)*5;updateTimePreview();};
  const stop=(e,cancel=false)=>{const d=cursorDrag;if(!d||e?.pointerId!=null&&e.pointerId!==d.pointerId)return;cursorDrag=null;if(d.el.hasPointerCapture(d.pointerId))d.el.releasePointerCapture(d.pointerId);d.el.classList.remove('is-dragging');if(cancel){cursorMinute=d.minute;updateTimePreview();}else saveCursor();};
  root.addEventListener('pointerdown',e=>{const el=e.target.closest('.dispatch-cursor');if(!el||e.button!==0||!e.isPrimary)return;const hours=root.querySelector('.dispatch-hours').getBoundingClientRect();cursorDrag={el,pointerId:e.pointerId,minute:cursorMinute,offset:e.clientX-hours.left-(cursorAbsolute()-scheduleAxis.start)/scheduleAxis.span*hours.width};el.setPointerCapture(e.pointerId);el.classList.add('is-dragging');el.focus({preventScroll:true});e.preventDefault();},{signal});
  root.addEventListener('pointermove',e=>{if(cursorDrag&&e.pointerId===cursorDrag.pointerId){moveCursor(e);e.preventDefault();}},{signal});
  root.addEventListener('pointerup',e=>stop(e),{signal});root.addEventListener('pointercancel',e=>stop(e,true),{signal});root.addEventListener('lostpointercapture',e=>stop(e,true),{signal});
  root.addEventListener('keydown',e=>{if(!e.target.closest('.dispatch-cursor'))return;const step=e.shiftKey?15:5,min=scheduleAxis.start-dayMinute(scheduleDate),max=scheduleAxis.end-dayMinute(scheduleDate);if(e.key==='Escape'){stop(null,true);return;}if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();cursorMinute=e.key==='Home'?min:e.key==='End'?max:Math.max(min,Math.min(max,cursorMinute+(e.key==='ArrowRight'?step:-step)));updateTimePreview();saveCursor();},{signal});
  window.addEventListener('blur',()=>stop(null,true),{signal});
  const observer=typeof ResizeObserver!=='undefined'?new ResizeObserver(()=>updateCursor()):null;observer?.observe(root);
  F.cleanup=()=>{stop(null,true);controller.abort();observer?.disconnect();scheduleRoot=null;};
}
function selectSchedulePlan(id,vehicleId){
  const scroll=scheduleRoot?.querySelector('.dispatch-scroll')?.scrollLeft||0;
  selectPlan(id);F.render();
  const scroller=scheduleRoot?.querySelector('.dispatch-scroll');if(scroller)scroller.scrollLeft=scroll;
  if(vehicleId){const button=[...scheduleRoot.querySelectorAll('[data-action="schedule-vehicle"]')].find(el=>el.dataset.id===vehicleId);button?.focus({preventScroll:true});}
}
function selectScheduleVehicle(vehicleId){
  const visible=filteredPlans().filter(p=>p.vehicleId===vehicleId).sort((a,b)=>planStart(a)-planStart(b));
  const available=visible.filter(p=>p.status!=='cancelled'),plans=available.length?available:visible,time=cursorAbsolute();
  const plan=plans.find(p=>planStart(p)<=time&&planEnd(p)>time)||plans.find(p=>planStart(p)>time)||plans[plans.length-1];
  if(plan)selectSchedulePlan(plan.id,vehicleId);
}
F.pages.plans={
  render(){
    if(F.state.justCreated){const p=F.plan();scheduleDate=p.date||'2026-10-23';scheduleQuery='';scheduleType=scheduleStatus='all';scheduleRange='today';cursorMinute=620;F.state.justCreated=false;}
    const stored=F.state.scheduleCursor;if(stored?.date===scheduleDate&&stored.range===scheduleRange&&Number.isFinite(stored.minute))cursorMinute=stored.minute;
    return `<section class="plans-page"><div class="page-head"><h1>任务与调度</h1><div class="row"><a class="btn subtle" href="#automation">${F.icon('flow',16)} 自动化流程</a><div class="segmented"><button data-action="schedule-view" data-mode="timeline" class="${scheduleView==='timeline'?'active':''}">▣ 时间轴</button><button data-action="schedule-view" data-mode="list" class="${scheduleView==='list'?'active':''}">☷ 任务清单</button></div><a class="btn primary" href="#create">＋ 创建运行计划</a></div></div><div class="schedule-toolbar"><label class="dispatch-date">${F.icon('clock',19)}<input id="schedule-date" type="date" value="${scheduleDate}" aria-label="计划日期"></label><div class="segmented">${[['today','今天'],['24h','未来24h'],['3days','近3天']].map(([key,text])=>`<button class="${scheduleRange===key?'active':''}" data-action="schedule-range" data-range="${key}">${text}</button>`).join('')}</div><button class="schedule-reset-time" data-action="schedule-reset-time" title="回到场景当前时间 10:20">回到当前</button><span class="toolbar-spacer"></span><select id="schedule-type" aria-label="计划类型"><option value="all">类型：全部</option>${[...new Set(F.state.plans.map(p=>p.type))].map(type=>`<option ${scheduleType===type?'selected':''}>${h(type)}</option>`).join('')}</select><select id="schedule-status" aria-label="计划状态"><option value="all">状态：全部</option>${['scheduled','waiting','running','completed','cancelled'].map(status=>`<option value="${status}" ${scheduleStatus===status?'selected':''}>${F.status[status][0]}</option>`).join('')}</select><input id="schedule-search" type="search" aria-label="搜索计划或车辆" placeholder="⌕ RT-021" value="${h(scheduleQuery)}"><button class="icon-btn" data-action="schedule-refresh" aria-label="清除筛选">↻</button></div><div id="schedule-content">${scheduleContents()}</div></section>`;
  },mount:mountSchedule,
  action(a,b){
    if(commonActions(a,b))return;
    if(a==='schedule-view'){scheduleView=b.dataset.mode;F.render();}
    if(a==='schedule-range'){scheduleRange=b.dataset.range;cursorMinute=620;saveCursor();F.render();}
    if(a==='schedule-select')selectSchedulePlan(b.dataset.id);
    if(a==='schedule-vehicle')selectScheduleVehicle(b.dataset.id);
    if(a==='schedule-refresh'){scheduleQuery='';scheduleType=scheduleStatus='all';scheduleRange='today';scheduleDate='2026-10-23';cursorMinute=620;saveCursor();F.render();F.toast('已恢复场景日期、当前时间并清除筛选');}
    if(a==='schedule-reset-time'){cursorMinute=620;saveCursor();updateTimePreview();const scroller=scheduleRoot.querySelector('.dispatch-scroll');if(scroller)scroller.scrollLeft=0;}
    if(a==='schedule-remote'&&F.plan().status!=='scheduled'){F.state.selectedId=F.plan().vehicleId;F.save();F.go('remote');}
    if(a==='schedule-time')adjustTime();if(a==='schedule-switch')switchVehicle();
    if(a==='schedule-cancel'){const p=F.plan();F.confirm('取消运行计划',`取消 ${p.id}（${p.vehicleId}）？原型中该计划将保留为“已取消”。`,()=>{const wasWaiting=p.status==='waiting';p.status='cancelled';const v=car(p.vehicleId);if(wasWaiting&&v.status==='waiting')v.status=F.state.plans.some(other=>other.id!==p.id&&other.vehicleId===v.id&&other.status==='waiting')?'waiting':'standby';F.log(`已取消计划 ${p.id}`);F.render();F.toast('计划已取消');},'确认取消');}
  }
};

function selectPlan(id){const p=F.state.plans.find(p=>p.id===id);if(p){F.state.selectedPlan=id;F.state.selectedId=p.vehicleId;F.save();}}
function commonActions(a,b){if(a==='select-plan'){selectPlan(b.dataset.id);const p=F.plan();scheduleDate=p.date||'2026-10-23';scheduleQuery='';scheduleType=scheduleStatus='all';F.go('plans');return true;}return false;}
function conflicts(vehicleId,start,end,except){return F.state.plans.some(p=>p.id!==except&&p.vehicleId===vehicleId&&!['cancelled','completed'].includes(p.status)&&(p.date||'2026-10-23')===(F.plan().date||'2026-10-23')&&minutes(start)<minutes(p.end)&&minutes(end)>minutes(p.start));}
function adjustTime(){const p=F.plan();F.modal('调整计划时段',`<p class="dialog-description" style="margin-bottom:18px">${h(p.id)} · ${h(p.vehicleId)}</p><div class="field-grid"><label class="field"><span>开始时间</span><input required type="time" name="start" value="${h(p.start)}"></label><label class="field"><span>结束时间</span><input required type="time" name="end" value="${h(p.end)}"></label></div><p id="schedule-form-error" class="red" role="alert" style="margin-top:12px"></p><div class="dialog-actions"><button type="button" class="btn subtle" data-action="close-modal">取消</button><button class="btn primary">保存时段</button></div>`,data=>{const start=data.get('start'),end=data.get('end');let error='';if(minutes(end)<=minutes(start))error='结束时间须晚于开始时间。';else if(conflicts(p.vehicleId,start,end,p.id))error='该车辆在此时段已有计划，请选择其他时间。';if(error){document.querySelector('#schedule-form-error').textContent=error;return false;}p.start=start;p.end=end;F.log(`计划 ${p.id} 调整至 ${start}–${end}`);F.toast('计划时段已更新');F.render();});}
function switchVehicle(){const p=F.plan(),choices=F.state.vehicles.filter(v=>['standby','waiting'].includes(v.status)&&v.id!==p.vehicleId);F.modal('更换执行车辆',`<p class="dialog-description" style="margin-bottom:16px">当前：${h(p.vehicleId)} · ${h(p.id)}</p><label class="field"><span>新执行车辆</span><select name="vehicle" required>${choices.map(v=>`<option value="${h(v.id)}">${h(v.id)} · SOC ${v.soc}% · ${h(v.plate)}</option>`).join('')}</select></label><p id="switch-error" class="red" role="alert"></p><div class="dialog-actions"><button type="button" class="btn subtle" data-action="close-modal">取消</button><button class="btn primary" ${!choices.length?'disabled':''}>确认换车</button></div>`,data=>{const id=data.get('vehicle');if(conflicts(id,p.start,p.end,p.id)){document.querySelector('#switch-error').textContent='该车辆在此时段已有计划。';return false;}const old=car(p.vehicleId);if(p.status==='waiting'&&old.status==='waiting')old.status=F.state.plans.some(other=>other.id!==p.id&&other.vehicleId===old.id&&other.status==='waiting')?'waiting':'standby';p.vehicleId=id;if(p.status==='waiting')car(id).status='waiting';F.state.selectedId=id;F.log(`计划 ${p.id} 从 ${old.id} 换车为 ${id}`);F.render();F.toast('计划执行车辆已更换');});}
F.pages.logs={render(){return `<section><div class="page-head"><div><h1>记录与交班</h1><p>本浏览器中的操作记录 · 共 ${F.state.logs.length} 条</p></div><div class="row"><button class="btn subtle" data-action="logs-export">导出操作记录</button><button class="btn primary" data-action="logs-handover">填写交班记录</button></div></div><div class="demo-note" style="margin-bottom:16px">原稿未提供此页，按侧栏入口补充演示。操作时间采用当前设备时间；初始记录沿用原稿场景。</div><section class="panel log-timeline">${F.state.logs.map(l=>`<article class="log-event"><time>${h(l.time)}</time><p>${h(l.text)}</p><span class="badge ${l.kind==='handover'?'blue':''}">${l.kind==='handover'?'交班记录':l.kind==='system'?'场景记录':'操作记录'}</span></article>`).join('')}</section></section>`;},action(a){if(a==='logs-export'){const csv='\uFEFF时间,类型,记录\r\n'+F.state.logs.map(l=>[l.time,l.kind,l.text].map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');download('ROPO-操作记录.csv',csv,'text/csv;charset=utf-8');F.toast('操作记录已导出');}if(a==='logs-handover'){F.modal('填写交班记录',`<label class="field"><span>接班人员</span><input name="person" placeholder="请输入接班人员" required maxlength="40"></label><label class="field"><span>需关注事项</span><textarea name="note" required placeholder="记录车辆异常、待执行计划及后续处理事项" maxlength="1000"></textarea></label><p class="muted">只保存本地记录，不会发送给接班人员。</p><div class="dialog-actions"><button type="button" class="btn subtle" data-action="close-modal">取消</button><button class="btn primary">保存交班记录</button></div>`,data=>{if(!data.get('person').trim()||!data.get('note').trim()){F.toast('请填写接班人员和关注事项','warning');return false;}F.log(`交班给 ${data.get('person')}：${data.get('note')}`,'handover');F.render();F.toast('交班记录已保存');});}}};
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
F.pages.settings={render(){return `<section><div class="page-head"><div><h1>系统设置</h1><p>演示环境与原型偏好</p></div></div><div class="settings-grid"><section class="panel settings-card"><h3>显示与浏览</h3><p>桌面布局沿用原稿 1440 px 设计基准。窄窗口可横向浏览复杂工作台。</p><label class="settings-option"><span>紧凑表格</span><input type="checkbox" id="setting-compact" ${F.state.settings?.compact?'checked':''}></label><div class="settings-option"><span>场景日期</span><span class="mono">2026-10-23</span></div><div class="settings-option"><span>存储位置</span><span>当前浏览器 localStorage</span></div></section><section class="panel settings-card"><h3>原型数据</h3><p>创建计划、发车状态、流程配置与操作记录保存在当前浏览器。恢复初始数据会清除这些本地修改。</p><button class="btn subtle" data-action="settings-export">导出演示状态 JSON</button><div class="divider"></div><button class="btn danger" data-action="settings-reset">恢复初始演示数据</button></section><section class="panel settings-card" style="grid-column:1/-1"><h3>关于本原型</h3><p>基于用户提供的七张 Figma SVG 重建。车辆编号已去重；所有统计值根据演示车辆计算。地图、摄像头和车辆图像来自原稿。流程编辑器、表单验证、弹窗与状态同步为根据画面补充的交互。</p><span class="badge blue">ROPO Fleet Prototype · v1.0</span></section></div></section>`;},mount(root){root.querySelector('#setting-compact').onchange=e=>{F.state.settings.compact=e.target.checked;document.body.classList.toggle('compact',e.target.checked);F.save();F.toast('显示偏好已保存');};},action(a){if(a==='settings-export')download('ROPO-演示状态.json',JSON.stringify(F.state,null,2),'application/json');if(a==='settings-reset')F.confirm('恢复初始演示数据','将清除当前浏览器中创建的计划、流程修改和操作记录。此操作仅影响原型。',()=>{F.state=F.seed();F.save();location.hash='overview';location.reload();},'恢复初始数据');}};
document.body.classList.toggle('compact',Boolean(F.state.settings?.compact));
})();
